#include <bits/stdc++.h>
#define int long long

using namespace std;
int n, H, M;
signed main() {
    freopen("bell.in", "r", stdin);
    freopen("bell.out", "w", stdout);
    ios::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    cin >> n >> H >> M;
    for (int i = 1; i <= n; i++) {
        int a, b;
        cin >> a >> b;
        M += a + b;
        H += M / 60;
        M %= 60;
        H %= 24;
    }
    cout << H << " " << M;
    return 0;
}
